jsonTools.init:
function init(eli) {
  if (!eli || !eli.bus || !eli.storage || !eli.compat) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded.admin_fleet;
  if (!bundle) return;

  // ── Constants ─────────────────────────────────────────────────────
  var GH_OWNER  = "apndrewn";
  var GH_REPO   = "eli-data";
  var GH_BRANCH = "main";
  var IDENTITY_PATH  = "fleet-identity.enc.json";
  var OVERRIDES_PATH = "admin-overrides.json";
  var STORE_CONFIG = "config";
  var LOCAL_LOOKUP_CACHE_KEY = "_admin_fleet_lookup_cache";

  // ── State ─────────────────────────────────────────────────────────
  var _lookup = {};            // userId → { email, firstName, lastName, role, notes, ... }
  var _telemetryByUserId = {}; // userId → fleet block (most recent)
  var _telemetryRowsByUserKey = {}; // userKey → full digest (for legacy users not in lookup)
  var _adminOverrides = null;  // current admin-overrides.json contents
  var _adminOverridesSha = null;
  var _identitySha = null;
  var _lookupLoaded = false;
  var _pat = null;
  var _password = null;
  var _userIdentity = null;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _ago(ts) {
    if (!ts) return "—";
    var d = (typeof ts === "number") ? ts : new Date(ts).getTime();
    var delta = Date.now() - d;
    if (!isFinite(delta) || delta < 0) return "—";
    var min = Math.floor(delta / 60000);
    if (min < 1) return "just now";
    if (min < 60) return min + " min ago";
    var hr = Math.floor(min / 60);
    if (hr < 24) return hr + "h ago";
    var day = Math.floor(hr / 24);
    if (day < 30) return day + "d ago";
    return new Date(d).toLocaleDateString();
  }
  function _toast(msg, kind) {
    if (typeof showToast === "function") showToast(msg, kind || "info");
  }

  // ── GitHub helpers ────────────────────────────────────────────────
  function _strToB64(s) {
    return btoa(unescape(encodeURIComponent(s)));
  }
  function _b64ToStr(b) {
    return decodeURIComponent(escape(atob(String(b || "").replace(/\s/g, ""))));
  }
  function _ghGet(path) {
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO +
      "/contents/" + encodeURIComponent(path) + "?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    var headers = {
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    };
    if (_pat) headers["Authorization"] = "Bearer " + _pat;
    return fetch(url, { cache: "no-store", headers: headers }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) return r.text().then(function (t) {
        throw new Error("GET " + path + ": HTTP " + r.status + " · " + t.slice(0, 200));
      });
      return r.json();
    });
  }
  function _ghPut(path, contentStr, message, existingSha) {
    if (!_pat) return Promise.reject(new Error("No GitHub PAT — import credentials first"));
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO + "/contents/" + encodeURIComponent(path);
    var body = { message: message, content: _strToB64(contentStr), branch: GH_BRANCH };
    if (existingSha) body.sha = existingSha;
    return fetch(url, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + _pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (r.ok) return r.json();
      return r.text().then(function (t) {
        throw new Error("PUT " + path + ": HTTP " + r.status + " · " + t.slice(0, 200));
      });
    }).then(function (result) {
      // Fire-and-forget jsdelivr purge
      var purge = "https://purge.jsdelivr.net/gh/" + GH_OWNER + "/" + GH_REPO + "@" + GH_BRANCH + "/" + path;
      fetch(purge, { method: "GET" }).catch(function () {});
      return result;
    });
  }

  // ── Credentials ───────────────────────────────────────────────────
  function _loadCredentials() {
    _pat = eli.compat.lsGet("eli_user_github_pat") || null;
    _password = eli.compat.lsGet("eli_admin_password") || null;
    try {
      _userIdentity = (eli.tools && typeof eli.tools.userIdentity === "function")
        ? eli.tools.userIdentity() : null;
    } catch (_e) {}
    return { hasPat: !!_pat, hasPassword: !!_password };
  }

  // ── Identity lookup (CDN encrypted) ──────────────────────────────
  function _fetchIdentityFromCdn() {
    return _ghGet(IDENTITY_PATH).then(function (r) {
      if (!r) return { lookup: {}, sha: null, isNew: true };
      _identitySha = r.sha;
      var content = _b64ToStr(r.content);
      var blob;
      try { blob = JSON.parse(content); }
      catch (e) { throw new Error("Identity file is not valid JSON: " + e.message); }
      if (!window._eliIsEncryptedBlob(blob)) {
        // Plain JSON (back-compat or pre-encryption state) — accept it.
        return { lookup: blob.identities || blob || {}, sha: r.sha, isNew: false };
      }
      if (!_password) throw new Error("Admin password missing — set eli_admin_password to decrypt identity map");
      return window._eliDecryptFromRepo(_password, blob).then(function (decrypted) {
        return { lookup: (decrypted && decrypted.identities) || {}, sha: r.sha, isNew: false, schemaVersion: decrypted.schemaVersion };
      });
    });
  }
  function _saveIdentityToCdn() {
    if (!_password) return Promise.reject(new Error("Admin password missing — cannot encrypt"));
    var payload = {
      schemaVersion: 1,
      encryptedAt: new Date().toISOString(),
      encryptedBy: (_userIdentity && _userIdentity.email) || "unknown",
      identities: _lookup,
    };
    return window._eliEncryptForRepo(_password, payload).then(function (blob) {
      var json = JSON.stringify(blob, null, 0);
      var msg = "admin_fleet: update identity map (" + Object.keys(_lookup).length + " users) @ " +
        new Date().toISOString().replace("T", " ").replace(/\..*/, "");
      return _ghPut(IDENTITY_PATH, json, msg, _identitySha).then(function (result) {
        _identitySha = result.content && result.content.sha;
        return true;
      });
    });
  }

  // ── Telemetry reading ─────────────────────────────────────────────
  // Telemetry files live at apndrewn/eli-data/usage/<userKey>.json
  // (per eli_telemetry's _githubPut → "usage/" + encodeURIComponent(userKey)).
  // userKey is the user's lowercase initials, e.g. "an", "jl" (per
  // etUserKey in eli_telemetry/engine.js).
  function _fetchAllTelemetry() {
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO + "/contents/usage?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    var headers = {
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    };
    if (_pat) headers["Authorization"] = "Bearer " + _pat;
    return fetch(url, { cache: "no-store", headers: headers }).then(function (r) {
      if (r.status === 404) return []; // usage folder doesn't exist yet
      if (!r.ok) return r.text().then(function (t) {
        throw new Error("List usage/: HTTP " + r.status + " · " + t.slice(0, 200));
      });
      return r.json();
    }).then(function (files) {
      // Filter: telemetry files are .json (skip .bak backups, hidden files)
      var telemetryFiles = (files || []).filter(function (f) {
        if (!f || f.type !== "file") return false;
        if (!/\.json$/.test(f.name)) return false;
        // Skip .bak files (created during clear operations)
        if (/\.bak/.test(f.name)) return false;
        return true;
      });
      var fetches = telemetryFiles.map(function (f) {
        var rawUrl = "https://raw.githubusercontent.com/" + GH_OWNER + "/" + GH_REPO + "/" + GH_BRANCH + "/usage/" + encodeURIComponent(f.name) + "?t=" + Date.now();
        return fetch(rawUrl, { cache: "no-store" }).then(function (r) {
          if (!r.ok) return null;
          return r.json();
        }).then(function (digest) {
          return { fileName: f.name, userKey: f.name.replace(/\.json$/, ""), digest: digest };
        }).catch(function () { return { fileName: f.name, userKey: f.name.replace(/\.json$/, ""), digest: null }; });
      });
      return Promise.all(fetches);
    });
  }
  function _indexTelemetry(rows) {
    _telemetryByUserId = {};
    _telemetryRowsByUserKey = {};
    (rows || []).forEach(function (r) {
      if (!r) return;
      _telemetryRowsByUserKey[r.userKey] = r.digest || {};
      var fleet = r.digest && r.digest.fleet;
      if (fleet && fleet.userId) {
        _telemetryByUserId[fleet.userId] = fleet;
      }
    });
  }

  // ── Admin overrides (push back) ──────────────────────────────────
  function _fetchAdminOverrides() {
    return _ghGet(OVERRIDES_PATH).then(function (r) {
      if (!r) {
        _adminOverrides = { schemaVersion: 1, lastUpdated: new Date().toISOString(), overrides: [] };
        _adminOverridesSha = null;
        return _adminOverrides;
      }
      _adminOverridesSha = r.sha;
      try {
        _adminOverrides = JSON.parse(_b64ToStr(r.content));
        if (!_adminOverrides.overrides) _adminOverrides.overrides = [];
      } catch (e) {
        _adminOverrides = { schemaVersion: 1, lastUpdated: new Date().toISOString(), overrides: [] };
      }
      return _adminOverrides;
    });
  }
  function _saveAdminOverrides() {
    if (!_adminOverrides) return Promise.reject(new Error("admin-overrides not loaded"));
    _adminOverrides.lastUpdated = new Date().toISOString();
    var json = JSON.stringify(_adminOverrides, null, 2);
    var count = (_adminOverrides.overrides || []).length;
    var msg = "admin_fleet: update overrides (" + count + " entries) @ " +
      new Date().toISOString().replace("T", " ").replace(/\..*/, "");
    return _ghPut(OVERRIDES_PATH, json, msg, _adminOverridesSha).then(function (result) {
      _adminOverridesSha = result.content && result.content.sha;
      return true;
    });
  }
  function _pushOverride(entry) {
    if (!_adminOverrides) return Promise.reject(new Error("admin-overrides not loaded yet"));
    // Strip any existing entry with same id (idempotent re-push)
    _adminOverrides.overrides = (_adminOverrides.overrides || []).filter(function (e) {
      return e.id !== entry.id;
    });
    _adminOverrides.overrides.push(entry);
    return _saveAdminOverrides();
  }
  function _removeOverride(id) {
    if (!_adminOverrides) return Promise.reject(new Error("admin-overrides not loaded yet"));
    var before = (_adminOverrides.overrides || []).length;
    _adminOverrides.overrides = (_adminOverrides.overrides || []).filter(function (e) {
      return e.id !== id;
    });
    if (_adminOverrides.overrides.length === before) return Promise.resolve(false);
    return _saveAdminOverrides();
  }

  // ── Bootstrap (fetch everything) ─────────────────────────────────
  function _bootstrap() {
    var creds = _loadCredentials();
    if (!creds.hasPat) {
      return Promise.reject(new Error("GitHub PAT missing. Import credentials via Admin Library Publisher first."));
    }
    if (!creds.hasPassword) {
      return Promise.reject(new Error("Admin password missing. Set eli_admin_password (e.g., via credentials bundle import)."));
    }
    return Promise.all([
      _fetchIdentityFromCdn().then(function (r) { _lookup = r.lookup || {}; _lookupLoaded = true; }),
      _fetchAllTelemetry().then(_indexTelemetry),
      _fetchAdminOverrides(),
    ]);
  }

  // ── Identity record helpers ──────────────────────────────────────
  function _identityFor(userId) { return _lookup[userId] || null; }
  function _displayName(userId) {
    var id = _identityFor(userId);
    if (!id) return userId;
    if (id.firstName && id.lastName) return id.firstName + " " + id.lastName;
    if (id.name) return id.name;
    if (id.email) return id.email;
    return userId;
  }
  function _displayRole(userId) {
    var id = _identityFor(userId);
    return (id && id.role) || "—";
  }
  function _email(userId) {
    var id = _identityFor(userId);
    return id && id.email;
  }
  // List of all users we know about — from three sources:
  //   1. Local lookup table (admin's identity map) — fully-known users
  //   2. Telemetry with fleet block — has userId, settings, tools
  //   3. Telemetry without fleet block (legacy files pre-fleet-payload) —
  //      surfaced by userKey (lowercase initials, e.g. "an", "jl") with
  //      a synthetic display id of "<INITIALS>-legacy"
  function _allUsers() {
    var ids = {};
    Object.keys(_lookup).forEach(function (k) { ids[k] = true; });
    Object.keys(_telemetryByUserId).forEach(function (k) { ids[k] = true; });
    // Legacy telemetry — files with no .fleet block. Synthesize a "legacy"
    // pseudo-id so they appear in the dashboard.
    Object.keys(_telemetryRowsByUserKey).forEach(function (uk) {
      var digest = _telemetryRowsByUserKey[uk];
      if (digest && digest.fleet && digest.fleet.userId) return; // already counted via fleet
      // No fleet block → use the userKey directly (e.g., "an" → "AN-legacy")
      var pseudoId = String(uk).toUpperCase() + "-legacy";
      if (!ids[pseudoId]) ids[pseudoId] = true;
    });
    return Object.keys(ids).sort();
  }
  function _unresolvedUsers() {
    return _allUsers().filter(function (uid) { return !_lookup[uid]; });
  }
  // Helper — for legacy synthetic IDs, return the original userKey.
  function _legacyUserKey(uid) {
    if (!/^[A-Z]+-legacy$/.test(uid)) return null;
    return uid.replace(/-legacy$/, "").toLowerCase();
  }

  // ── Dialog: identity add/edit ────────────────────────────────────
  function _showIdentityEditor(userId, isNew) {
    if (typeof showEliDialog !== "function") {
      _toast("showEliDialog unavailable", "err");
      return;
    }
    var existing = _identityFor(userId) || {};
    var fleet = _telemetryByUserId[userId] || {};
    var prefilledInitials = fleet.initials || (userId.split("-")[0]) || "";
    var firstHint = "";
    var lastHint = "";
    if (prefilledInitials.length >= 1) firstHint = prefilledInitials.charAt(0);
    if (prefilledInitials.length >= 2) lastHint = prefilledInitials.charAt(1);

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User ID</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(userId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Initials hint</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(prefilledInitials || "—") + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Email <span class="_eli3_af_req">*</span></label>' +
          '<input type="email" id="_af_form_email" value="' + _esc(existing.email || "") + '" placeholder="user@example.com" required>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>First name</label>' +
          '<input type="text" id="_af_form_first" value="' + _esc(existing.firstName || (firstHint ? firstHint + "..." : "")) + '" placeholder="Jared">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Last name</label>' +
          '<input type="text" id="_af_form_last" value="' + _esc(existing.lastName || (lastHint ? "..." + lastHint : "")) + '" placeholder="Lerner">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Role</label>' +
          '<select id="_af_form_role">' +
            ['', 'admin', 'attorney', 'intern', 'observer', 'other'].map(function (r) {
              var sel = (existing.role === r || (!existing.role && !r)) ? " selected" : "";
              return '<option value="' + r + '"' + sel + '>' + (r || "—") + '</option>';
            }).join('') +
          '</select>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Team</label>' +
          '<input type="text" id="_af_form_team" value="' + _esc(existing.team || "") + '" placeholder="(optional)">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Status</label>' +
          '<select id="_af_form_status">' +
            ['active', 'trial', 'offboarded'].map(function (s) {
              var sel = (existing.status || "active") === s ? " selected" : "";
              return '<option value="' + s + '"' + sel + '>' + s + '</option>';
            }).join('') +
          '</select>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Notes</label>' +
          '<textarea id="_af_form_notes" rows="2" placeholder="(optional)">' + _esc(existing.notes || "") + '</textarea>' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: isNew ? "🆕" : "✏️",
      title: isNew ? "Identify new user" : "Edit user",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          closeOnClick: true,
        },
        {
          label: isNew ? "Save identity" : "Save changes",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var email = (document.getElementById("_af_form_email").value || "").trim();
            if (!email || !/@/.test(email)) {
              _toast("Email required", "err");
              return false;
            }
            var record = {
              email: email,
              firstName: (document.getElementById("_af_form_first").value || "").trim(),
              lastName:  (document.getElementById("_af_form_last").value || "").trim(),
              role:      document.getElementById("_af_form_role").value || "",
              team:      (document.getElementById("_af_form_team").value || "").trim(),
              status:    document.getElementById("_af_form_status").value || "active",
              notes:     (document.getElementById("_af_form_notes").value || "").trim(),
              initials:  prefilledInitials,
              addedAt:   existing.addedAt || new Date().toISOString(),
              lastUpdated: new Date().toISOString(),
            };
            _lookup[userId] = record;
            _toast("⏳ Saving identity map…", "info");
            _saveIdentityToCdn().then(function () {
              _toast("✅ Identity saved", "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Save failed: " + err.message, "err");
              // Revert local change
              delete _lookup[userId];
              if (existing && existing.email) _lookup[userId] = existing;
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: setting change push ──────────────────────────────────
  function _showSettingPusher(userId) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var fleet = _telemetryByUserId[userId] || {};
    var currentSettings = fleet.settings || {};

    // Known setting keys (could be discovered from telemetry too)
    var KNOWN_SETTINGS = [
      { key: "ai_model", label: "AI Model", type: "string" },
      { key: "ai_temperature", label: "AI Temperature", type: "number" },
      { key: "ai_timeout_ms", label: "AI Timeout (ms)", type: "number" },
      { key: "ai_thinking_budget", label: "AI Thinking Budget", type: "number" },
      { key: "ai_allow_streaming", label: "AI Streaming", type: "boolean" },
      { key: "expand_width", label: "Expand Width", type: "number" },
      { key: "expand_threshold", label: "Expand Threshold", type: "number" },
      { key: "debug_mode", label: "Debug Mode", type: "boolean" },
    ];

    var rows = KNOWN_SETTINGS.map(function (s) {
      var cur = currentSettings.hasOwnProperty(s.key) ? currentSettings[s.key] : "—";
      return '<option value="' + _esc(s.key) + '" data-type="' + s.type + '">' +
        _esc(s.label) + ' (current: ' + _esc(String(cur)) + ')</option>';
    }).join("");

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Setting</label>' +
          '<select id="_af_set_key">' + rows + '</select>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>New value</label>' +
          '<input type="text" id="_af_set_val" placeholder="e.g., gemini-3.1-pro">' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Mode</label>' +
          '<div>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_set_mode" value="reset" checked> ' +
              '<b>Reset</b> — push to user pref (editable after)</label><br>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_set_mode" value="true"> ' +
              '<b>Force</b> — locked, user can\'t change</label><br>' +
            '<label class="_eli3_af_radio"><input type="radio" name="_af_set_mode" value="false"> ' +
              '<b>Soft</b> — only applies if user has no pref</label>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason (note)</label>' +
          '<input type="text" id="_af_set_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: "⚙️",
      title: "Push setting change",
      body: bodyHtml,
      buttons: [
        { label: "Cancel", cls: "btn-secondary", closeOnClick: true },
        {
          label: "Push to " + _displayName(userId),
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var key = document.getElementById("_af_set_key").value;
            var rawVal = (document.getElementById("_af_set_val").value || "").trim();
            if (!rawVal) { _toast("Value required", "err"); return false; }
            var modeStr = (document.querySelector('input[name="_af_set_mode"]:checked') || {}).value || "reset";
            var force = (modeStr === "true") ? true : (modeStr === "reset" ? "reset" : false);
            // Type-cast based on the setting's declared type
            var typeStr = document.querySelector("#_af_set_key option:checked").getAttribute("data-type");
            var val = rawVal;
            if (typeStr === "number") val = Number(rawVal);
            else if (typeStr === "boolean") val = (rawVal === "true" || rawVal === "1");
            var reason = (document.getElementById("_af_set_reason").value || "").trim();

            var overrideId = "fleet-set-" + key + "-" + userId + "-" + Date.now();
            var entry = {
              id: overrideId,
              audienceEmails: [id.email],
              actions: [{
                type: "set_setting",
                key: key,
                value: val,
                force: force,
              }],
              pushedAt: new Date().toISOString(),
              pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
            };
            if (reason) entry.note = reason;

            _toast("⏳ Pushing override…", "info");
            _pushOverride(entry).then(function () {
              _toast("✅ Pushed " + key + " → " + val + " to " + _displayName(userId), "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Push failed: " + err.message, "err");
            });

            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dialog: tool action push ─────────────────────────────────────
  function _showToolPusher(userId, toolId, action) {
    if (typeof showEliDialog !== "function") return;
    var id = _identityFor(userId);
    if (!id || !id.email) {
      _toast("Identify user first (need their email)", "err");
      return;
    }
    var actionType = action; // "disable_tool" | "enable_tool" | "force_redownload_tool"
    var actionLabel = {
      disable_tool: "Disable",
      enable_tool: "Enable",
      force_redownload_tool: "Force re-download (uninstall + re-install)",
    }[actionType] || actionType;

    var bodyHtml =
      '<div class="_eli3_af_form">' +
        '<div class="_eli3_af_form_row">' +
          '<label>User</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(_displayName(userId)) + ' (' + _esc(id.email) + ')</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Tool</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(toolId) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Action</label>' +
          '<div class="_eli3_af_form_val_static">' + _esc(actionLabel) + '</div>' +
        '</div>' +
        '<div class="_eli3_af_form_row">' +
          '<label>Reason</label>' +
          '<input type="text" id="_af_tool_reason" placeholder="(optional admin note)">' +
        '</div>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      icon: "🛠️",
      title: "Push tool action",
      body: bodyHtml,
      buttons: [
        { label: "Cancel", cls: "btn-secondary", closeOnClick: true },
        {
          label: "Push",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var reason = (document.getElementById("_af_tool_reason").value || "").trim();
            var overrideId = "fleet-" + actionType + "-" + toolId + "-" + userId + "-" + Date.now();
            var entry = {
              id: overrideId,
              audienceEmails: [id.email],
              actions: [{ type: actionType, toolId: toolId }],
              pushedAt: new Date().toISOString(),
              pushedBy: (_userIdentity && _userIdentity.email) || "unknown",
            };
            if (reason) entry.note = reason;
            _toast("⏳ Pushing override…", "info");
            _pushOverride(entry).then(function () {
              _toast("✅ " + actionLabel + " pushed for " + toolId, "ok");
              _renderDashboard();
            }).catch(function (err) {
              _toast("Push failed: " + err.message, "err");
            });
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
          },
        },
      ],
    });
  }

  // ── Dashboard rendering ──────────────────────────────────────────
  function _renderDashboard() {
    var out = window.eli.ui.claimOutput();
    out.classList.add("eli-view-enter");

    var unresolved = _unresolvedUsers();
    var resolved = _allUsers().filter(function (uid) { return _lookup[uid]; });
    var overridesByEmail = {};
    (_adminOverrides && _adminOverrides.overrides || []).forEach(function (o) {
      (o.audienceEmails || []).forEach(function (em) {
        if (!overridesByEmail[em]) overridesByEmail[em] = [];
        overridesByEmail[em].push(o);
      });
    });

    function _renderUserCard(userId) {
      var id = _identityFor(userId);
      var fleet = _telemetryByUserId[userId];
      // Legacy fallback — for "AN-legacy" style synthetic IDs that have a
      // telemetry file but no fleet block yet, pull what we can from the
      // raw digest (days array, etc.) so the card isn't entirely empty.
      var legacyKey = _legacyUserKey(userId);
      var legacyDigest = legacyKey ? _telemetryRowsByUserKey[legacyKey] : null;
      var isLegacy = !!legacyDigest && !fleet;
      var nm = id ? _displayName(userId) : userId;
      var role = id && id.role ? id.role : "—";
      var status = id && id.status ? id.status : "—";
      var email = id && id.email ? id.email : "—";
      var lastSeen = fleet && fleet.lastSeenAt ? _ago(fleet.lastSeenAt)
        : (legacyDigest && legacyDigest.days && legacyDigest.days.length
            ? "legacy: last day " + legacyDigest.days[legacyDigest.days.length - 1].date
            : "never");
      var installedAt = fleet && fleet.installedAt ? new Date(fleet.installedAt).toLocaleDateString() : "—";
      var aiModel = fleet && fleet.settings && fleet.settings.ai_model || "—";
      var kernelV = fleet && fleet.kernelVersion || "—";
      var toolCount = fleet && fleet.tools ? fleet.tools.length : 0;
      var activeOverrides = email !== "—" ? (overridesByEmail[email] || []) : [];

      var statusBadge = '<span class="_eli3_af_badge _eli3_af_badge_' + _esc(status) + '">' + _esc(status) + '</span>';
      var roleBadge = role !== "—" ? '<span class="_eli3_af_badge _eli3_af_badge_role">' + _esc(role) + '</span>' : '';
      var legacyBadge = isLegacy
        ? '<span class="_eli3_af_badge _eli3_af_badge_legacy" title="Telemetry exists but pre-dates fleet payload. Next push from this user will populate full fleet data.">⏳ legacy</span>'
        : '';

      var actionsHtml = '';
      if (id) {
        actionsHtml =
          '<button class="_eli3_af_btn _eli3_af_btn_primary" data-act="push-setting" data-uid="' + _esc(userId) + '">⚙️ Push setting</button>' +
          '<button class="_eli3_af_btn" data-act="edit-identity" data-uid="' + _esc(userId) + '">✏️ Edit identity</button>';
      } else {
        actionsHtml =
          '<button class="_eli3_af_btn _eli3_af_btn_primary" data-act="add-identity" data-uid="' + _esc(userId) + '">🆕 Identify this user</button>';
      }

      var toolsList = "";
      if (fleet && fleet.tools && fleet.tools.length) {
        toolsList = '<div class="_eli3_af_tools">' +
          '<div class="_eli3_af_tools_header">Tools (' + fleet.tools.length + ')</div>' +
          '<div class="_eli3_af_tools_list">' +
            fleet.tools.map(function (t) {
              var disabledMark = t.disabled ? ' <span class="_eli3_af_tools_disabled">(disabled)</span>' : '';
              return '<div class="_eli3_af_tools_row">' +
                '<span class="_eli3_af_tools_id">' + _esc(t.id) + '</span>' +
                disabledMark +
                (id ? (
                  '<div class="_eli3_af_tools_actions">' +
                    (t.disabled
                      ? '<button class="_eli3_af_btn_mini" data-act="tool-enable" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">▶ Enable</button>'
                      : '<button class="_eli3_af_btn_mini" data-act="tool-disable" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">⏸ Disable</button>') +
                    '<button class="_eli3_af_btn_mini" data-act="tool-redownload" data-uid="' + _esc(userId) + '" data-tool="' + _esc(t.id) + '">↺ Re-DL</button>' +
                  '</div>'
                ) : '') +
              '</div>';
            }).join('') +
          '</div>' +
        '</div>';
      }

      var settingsList = "";
      if (fleet && fleet.settings) {
        var sKeys = Object.keys(fleet.settings).filter(function (k) {
          var v = fleet.settings[k];
          return v !== null && v !== undefined && v !== "";
        });
        if (sKeys.length) {
          settingsList = '<div class="_eli3_af_settings">' +
            '<div class="_eli3_af_settings_header">Settings (' + sKeys.length + ')</div>' +
            '<div class="_eli3_af_settings_list">' +
              sKeys.map(function (k) {
                return '<div class="_eli3_af_settings_row">' +
                  '<span class="_eli3_af_settings_key">' + _esc(k) + ':</span> ' +
                  '<span class="_eli3_af_settings_val">' + _esc(String(fleet.settings[k])) + '</span>' +
                '</div>';
              }).join('') +
            '</div>' +
          '</div>';
        }
      }

      var overridesList = "";
      if (activeOverrides.length) {
        overridesList = '<div class="_eli3_af_overrides">' +
          '<div class="_eli3_af_overrides_header">Active admin pushes (' + activeOverrides.length + ')</div>' +
          activeOverrides.map(function (o) {
            var actionSummary = (o.actions || []).map(function (a) {
              if (a.type === "set_setting") return a.key + " = " + JSON.stringify(a.value) + " (" + (a.force === true ? "force" : a.force === "reset" ? "reset" : "soft") + ")";
              if (a.type === "disable_tool") return "disable " + a.toolId;
              if (a.type === "enable_tool") return "enable " + a.toolId;
              if (a.type === "force_redownload_tool") return "re-download " + a.toolId;
              return a.type;
            }).join("; ");
            return '<div class="_eli3_af_overrides_row">' +
              '<span>' + _esc(actionSummary) + '</span>' +
              ' <button class="_eli3_af_btn_mini _eli3_af_btn_danger" data-act="remove-override" data-oid="' + _esc(o.id) + '">🗑 Remove</button>' +
            '</div>';
          }).join('') +
        '</div>';
      }

      return '<div class="_eli3_af_card" data-uid="' + _esc(userId) + '">' +
        '<div class="_eli3_af_card_header">' +
          '<div class="_eli3_af_card_name">' + _esc(nm) + '</div>' +
          '<div class="_eli3_af_card_badges">' + roleBadge + statusBadge + legacyBadge + '</div>' +
        '</div>' +
        '<div class="_eli3_af_card_meta">' +
          '<span title="User ID">' + _esc(userId) + '</span>' +
          ' · <span title="Email">' + _esc(email) + '</span>' +
          ' · <span title="Last telemetry upload">last seen ' + _esc(lastSeen) + '</span>' +
          ' · <span title="Install date">installed ' + _esc(installedAt) + '</span>' +
          ' · <span title="Kernel version">' + _esc(kernelV) + '</span>' +
          ' · <span title="Tools count">' + toolCount + ' tools</span>' +
          ' · <span title="Current AI model">model: ' + _esc(aiModel) + '</span>' +
        '</div>' +
        '<div class="_eli3_af_card_actions">' + actionsHtml + '</div>' +
        settingsList +
        toolsList +
        overridesList +
      '</div>';
    }

    var headerHtml =
      '<div class="_eli3_af_header">' +
        '<div class="_eli3_af_header_title">' +
          '<span class="_eli3_af_header_icon">👥</span>' +
          '<span>ELI Fleet</span>' +
        '</div>' +
        '<div class="_eli3_af_header_meta">' +
          _allUsers().length + ' users · ' +
          unresolved.length + ' unresolved · ' +
          (_adminOverrides && _adminOverrides.overrides ? _adminOverrides.overrides.length : 0) + ' active pushes' +
        '</div>' +
        '<div class="_eli3_af_header_actions">' +
          '<button class="_eli3_af_btn" id="_af_refresh">🔄 Refresh</button>' +
          '<button class="_eli3_af_btn" id="_af_close">✕ Close</button>' +
        '</div>' +
      '</div>';

    var unresolvedHtml = "";
    if (unresolved.length) {
      unresolvedHtml = '<div class="_eli3_af_section">' +
        '<div class="_eli3_af_section_header">🆕 Unresolved users — click "Identify" to add them to your lookup</div>' +
        unresolved.map(_renderUserCard).join("") +
      '</div>';
    }

    var resolvedHtml = '<div class="_eli3_af_section">' +
      '<div class="_eli3_af_section_header">Resolved users (' + resolved.length + ')</div>' +
      (resolved.length ? resolved.map(_renderUserCard).join("") :
        '<div class="_eli3_af_empty">No users in the lookup table yet. Identify one above to get started.</div>') +
    '</div>';

    out.innerHTML =
      '<div class="_eli3_af_root">' +
        headerHtml +
        unresolvedHtml +
        resolvedHtml +
      '</div>';

    // Wire actions
    document.getElementById("_af_refresh").onclick = function () { _launch(true); };
    document.getElementById("_af_close").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    out.addEventListener("click", function (ev) {
      var t = ev.target;
      while (t && t !== out) {
        var act = t.getAttribute && t.getAttribute("data-act");
        if (act) {
          var uid = t.getAttribute("data-uid");
          if (act === "add-identity") return _showIdentityEditor(uid, true);
          if (act === "edit-identity") return _showIdentityEditor(uid, false);
          if (act === "push-setting") return _showSettingPusher(uid);
          if (act === "tool-disable") return _showToolPusher(uid, t.getAttribute("data-tool"), "disable_tool");
          if (act === "tool-enable") return _showToolPusher(uid, t.getAttribute("data-tool"), "enable_tool");
          if (act === "tool-redownload") return _showToolPusher(uid, t.getAttribute("data-tool"), "force_redownload_tool");
          if (act === "remove-override") {
            var oid = t.getAttribute("data-oid");
            if (!oid) return;
            _toast("⏳ Removing override…", "info");
            _removeOverride(oid).then(function (ok) {
              if (ok) _toast("✅ Override removed", "ok");
              _renderDashboard();
            }).catch(function (err) { _toast("Remove failed: " + err.message, "err"); });
            return;
          }
        }
        t = t.parentNode;
      }
    });
  }

  function _launch(force) {
    _toast("⏳ Loading fleet data…", "info");
    return _bootstrap().then(function () {
      _renderDashboard();
      eli.log.event("tool", "admin_fleet_loaded", {
        users: _allUsers().length,
        unresolved: _unresolvedUsers().length,
        overrides: (_adminOverrides && _adminOverrides.overrides || []).length,
      });
    }).catch(function (err) {
      _toast("Fleet load failed: " + (err.message || "unknown"), "err");
      eli.log.event("tool", "admin_fleet_load_failed", { msg: err && err.message });
      // Render a fallback message
      var out = window.eli.ui.claimOutput();
      out.innerHTML =
        '<div class="_eli3_af_root">' +
          '<div class="_eli3_af_error">' +
            '<h2>👥 ELI Fleet — Setup needed</h2>' +
            '<p>' + _esc(err.message || "Unknown error") + '</p>' +
            '<p>Make sure both <code>eli_user_github_pat</code> and <code>eli_admin_password</code> are set ' +
              '(usually via importing a credentials bundle in Admin Library Publisher).</p>' +
            '<button class="_eli3_af_btn" id="_af_retry">🔄 Retry</button>' +
          '</div>' +
        '</div>';
      document.getElementById("_af_retry").onclick = function () { _launch(); };
    });
  }

  // ── Tile registration ────────────────────────────────────────────
  if (eli.register) {
    eli.register({
      tile: {
        app_admin_fleet: eli.events.guard ? eli.events.guard(function () { _launch(); }, "admin_fleet.tile") : function () { _launch(); },
      },
    });
  }

  eli.log.event("tool", "admin_fleet_initialized", {});
}

jsonTools.css:
/* admin_fleet — fleet dashboard styling
   Light palette in both themes (per CLAUDE.md tools+dialogs rule). */

._eli3_af_root {
  font: 13px/1.4 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 16px;
  min-height: 100vh;
  box-sizing: border-box;
}

._eli3_af_header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  border-radius: 0;
  margin-bottom: 14px;
}
._eli3_af_header_title {
  font-family: 'Georgia', serif;
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}
._eli3_af_header_icon { font-size: 20px; }
._eli3_af_header_meta {
  font-size: 11px;
  color: #cbd5e1;
  letter-spacing: 0.5px;
  flex: 1;
}
._eli3_af_header_actions {
  display: flex;
  gap: 6px;
}
._eli3_af_header_actions ._eli3_af_btn {
  background: rgba(255,255,255,0.15);
  border-color: rgba(255,255,255,0.3);
  color: #fff;
}
._eli3_af_header_actions ._eli3_af_btn:hover {
  background: rgba(255,255,255,0.25);
}

._eli3_af_section {
  margin-bottom: 16px;
}
._eli3_af_section_header {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  padding: 8px 4px;
  border-bottom: 1px solid #cbd5e1;
  margin-bottom: 8px;
}
._eli3_af_empty {
  padding: 24px 12px;
  text-align: center;
  color: #94a3b8;
  font-size: 12px;
}

._eli3_af_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 12px 14px;
  margin-bottom: 8px;
}
._eli3_af_card[data-uid] ._eli3_af_card_header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 4px;
}
._eli3_af_card_name {
  font: 700 14px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_af_card_badges {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}
._eli3_af_badge {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 6px;
  border-radius: 2px;
}
._eli3_af_badge_role {
  background: #e0e7ff; color: #3730a3; border: 1px solid #c7d2fe;
}
._eli3_af_badge_active {
  background: #dcfce7; color: #14532d; border: 1px solid #86efac;
}
._eli3_af_badge_trial {
  background: #fef3c7; color: #92400e; border: 1px solid #fde68a;
}
._eli3_af_badge_offboarded {
  background: #f1f5f9; color: #64748b; border: 1px solid #cbd5e1;
}
._eli3_af_badge_legacy {
  background: #fde68a; color: #78350f; border: 1px solid #fbbf24;
}

._eli3_af_card_meta {
  font: 500 10.5px/1.4 'Inter', sans-serif;
  color: #64748b;
  margin-bottom: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}
._eli3_af_card_meta span { white-space: nowrap; }

._eli3_af_card_actions {
  display: flex;
  gap: 6px;
  margin: 6px 0;
  flex-wrap: wrap;
}

._eli3_af_btn {
  font: 600 11px/1 'Inter', sans-serif;
  padding: 6px 10px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-bottom-width: 2px;
  color: #0f172a;
  cursor: pointer;
  border-radius: 3px;
  transition: filter 0.12s;
}
._eli3_af_btn:hover { filter: brightness(0.97); }
._eli3_af_btn_primary {
  background: linear-gradient(180deg, #1565c0 0%, #0d47a1 100%);
  border-color: #0d47a1;
  color: #fff;
}
._eli3_af_btn_primary:hover { filter: brightness(1.08); }

._eli3_af_btn_mini {
  font: 600 10px/1 'Inter', sans-serif;
  padding: 3px 6px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 2px;
  transition: filter 0.12s;
}
._eli3_af_btn_mini:hover { filter: brightness(0.95); }
._eli3_af_btn_danger {
  background: linear-gradient(180deg, #fef2f2 0%, #fee2e2 100%);
  border-color: #fca5a5;
  color: #991b1b;
}

._eli3_af_settings,
._eli3_af_tools,
._eli3_af_overrides {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
  font-size: 11px;
}
._eli3_af_settings_header,
._eli3_af_tools_header,
._eli3_af_overrides_header {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #475569;
  margin-bottom: 4px;
}
._eli3_af_settings_list,
._eli3_af_tools_list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px 12px;
}
._eli3_af_settings_row,
._eli3_af_tools_row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  color: #475569;
  padding: 1px 0;
}
._eli3_af_settings_key { font-weight: 700; color: #0f172a; }
._eli3_af_settings_val { color: #1565c0; }
._eli3_af_tools_id { flex: 1; color: #0f172a; }
._eli3_af_tools_disabled { color: #b91c1c; font-weight: 700; font-size: 9px; }
._eli3_af_tools_actions { display: flex; gap: 2px; }

._eli3_af_overrides_row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 6px;
  background: #fef3c7;
  border: 1px solid #fde68a;
  margin-bottom: 3px;
  font-size: 10.5px;
  color: #92400e;
}

._eli3_af_form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eli3_af_form_row {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 10px;
  align-items: center;
}
._eli3_af_form_row label {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
._eli3_af_form_row input,
._eli3_af_form_row select,
._eli3_af_form_row textarea {
  font: 500 12px/1.3 'Inter', sans-serif;
  padding: 6px 8px;
  border: 1px solid #cbd5e1;
  border-radius: 2px;
  background: #fff;
  color: #0f172a;
  outline: none;
  width: 100%;
  box-sizing: border-box;
}
._eli3_af_form_row input:focus,
._eli3_af_form_row select:focus,
._eli3_af_form_row textarea:focus {
  border-color: #1565c0;
}
._eli3_af_form_val_static {
  font: 500 11.5px/1.3 'Inter', sans-serif;
  color: #475569;
  padding: 4px 0;
}
._eli3_af_req { color: #b91c1c; }
._eli3_af_radio {
  display: inline-block;
  padding: 2px 0;
  font-size: 11px;
}

._eli3_af_error {
  background: #fff;
  border: 1px solid #fca5a5;
  border-left: 4px solid #b91c1c;
  padding: 16px;
  border-radius: 0;
}
